"""slowbook.py -- brutally simple reference order book (linear scans).

Same semantics as fastbook.py:
  * price-time priority (best price first, earliest arrival breaks ties),
  * partial fills allowed, trades print at the RESTING price,
  * market orders sweep until filled or the book is empty; remainder is
    discarded (market taker id is 0),
  * cancelling an unknown/already-filled id is a no-op.

Everything is an unsorted Python list scanned end-to-end. Correctness over
speed; it exists solely to differential-test the fast book against.
"""


class SlowBook:
    __slots__ = ('bids', 'asks', 'trades')

    def __init__(self):
        self.bids = []      # list of [oid, price, qty], arrival order
        self.asks = []
        self.trades = []    # tape of (buy_id, sell_id, price, qty)

    # ---- linear scans for the current best ---------------------------
    def _best_bid(self):
        best = None
        for o in self.bids:                 # highest price, then earliest
            if best is None or o[1] > best[1]:
                best = o
        return best

    def _best_ask(self):
        best = None
        for o in self.asks:                 # lowest price, then earliest
            if best is None or o[1] < best[1]:
                best = o
        return best

    # ------------------------------------------------------------- ops --
    def add_limit(self, side, oid, price, qty):
        if side == 'B':
            while qty > 0:
                t = self._best_ask()
                if t is None or t[1] > price:       # not marketable
                    break
                f = qty if qty < t[2] else t[2]
                self.trades.append((oid, t[0], t[1], f))   # resting price
                qty -= f
                t[2] -= f
                if t[2] == 0:
                    self.asks.remove(t)
            if qty > 0:
                self.bids.append([oid, price, qty])
        else:
            while qty > 0:
                t = self._best_bid()
                if t is None or t[1] < price:
                    break
                f = qty if qty < t[2] else t[2]
                self.trades.append((t[0], oid, t[1], f))
                qty -= f
                t[2] -= f
                if t[2] == 0:
                    self.bids.remove(t)
            if qty > 0:
                self.asks.append([oid, price, qty])

    def add_market(self, side, qty, taker_id=0):
        if side == 'B':
            while qty > 0:
                t = self._best_ask()
                if t is None:
                    break                           # book exhausted: discard
                f = qty if qty < t[2] else t[2]
                self.trades.append((taker_id, t[0], t[1], f))
                qty -= f
                t[2] -= f
                if t[2] == 0:
                    self.asks.remove(t)
        else:
            while qty > 0:
                t = self._best_bid()
                if t is None:
                    break
                f = qty if qty < t[2] else t[2]
                self.trades.append((t[0], taker_id, t[1], f))
                qty -= f
                t[2] -= f
                if t[2] == 0:
                    self.bids.remove(t)

    def cancel(self, oid):
        for i, o in enumerate(self.bids):
            if o[0] == oid:
                del self.bids[i]
                return
        for i, o in enumerate(self.asks):
            if o[0] == oid:
                del self.asks[i]
                return

    # -------------------------------------------------------- queries --
    def depth(self):
        bd, ad = {}, {}
        for o in self.bids:
            bd[o[1]] = bd.get(o[1], 0) + o[2]
        for o in self.asks:
            ad[o[1]] = ad.get(o[1], 0) + o[2]
        return sorted(bd.items(), reverse=True), sorted(ad.items())

    def apply(self, op):
        c = op[0]
        if c == 'L':
            self.add_limit(op[1], op[2], op[3], op[4])
        elif c == 'C':
            self.cancel(op[1])
        else:
            self.add_market(op[1], op[2])

